package dev.starfold;

import dev.starfold.BentStripGeometry.Point;
import dev.starfold.CubeSurfaceTopology.Face;
import java.util.*;

/** Local repair of the old net's FAR missing quadrant. Never a sphere/tangent projection.
 * The current face, all Y coordinates, and the 32-block player neighbourhood are unchanged.
 * A 30-degree angular transition on either side of the direction opposite the player
 * borrows the real far border strips; the total added angle is at most 90 degrees.
 * Each donor is rendered once; this moves its real border strip rather than copying blocks.
 * Unrepairable near cuts remain explicit, instead of relaxing the protected neighbourhood.
 * Optional GroundAir lifts those display restrictions above the configured start height.
 * CPU counterpart of ground_gap.vsh. */
public final class GroundGap {
    public static final double NEAR=32,GRID=16,GUARD=56,BLEND=32,BAND=Math.PI/6;
    public final GroundChart chart;
    public final Point eye,corner;
    public final double sx,sz,distance,clip,strength,outer;
    public final GroundAir air;
    /** Explicit accepted alpha.53 ground-only branch, also used by baseline comparisons. */
    public GroundGap(Face root,Point eye,int view,boolean enabled){this(root,eye,view,enabled,GroundAir.DEFAULT,false);}
    public GroundGap(Face root,Point eye,int view,boolean enabled,GroundAir.Config heights,boolean airEnabled){
        if(eye==null||!eye.finite()||view<32||view>1024)throw new IllegalArgumentException("Gap view");
        chart=new GroundChart(root);this.eye=eye;clip=view+24;
        corner=new Point(eye.x()<GroundSpace.SIZE/2.0?0:GroundSpace.SIZE,0,eye.z()<GroundSpace.SIZE/2.0?0:GroundSpace.SIZE);
        sx=corner.x()==0?1:-1;sz=corner.z()==0?1:-1;
        distance=Math.hypot(eye.x()-corner.x(),eye.z()-corner.z());
        strength=enabled?1-smooth(clip-BLEND,clip,distance):0;outer=clip+distance+32;
        air=new GroundAir(root,eye,heights,enabled&&airEnabled);
    }
    public static double smooth(double low,double high,double value){double t=Math.clamp((value-low)/(high-low),0,1);return t*t*(3-2*t);}
    /** Affected source, destination and intermediate arcs stay in the half-plane behind the vertex. */
    public double amplitude(double r){
        double minDistance=Math.hypot(distance,r);
        return strength*smooth(GUARD,GUARD+BLEND,minDistance)*(1-smooth(outer,2*outer,r));
    }
    public Point raw(Point p){
        if(strength==0)return p;
        double x=(p.x()-corner.x())*sx,z=(p.z()-corner.z())*sz;
        if(!(x<0&&z>=0||z<0&&x>=0))return p;
        double theta=x<0?Math.PI-Math.atan2(Math.max(0,z),-x):-Math.PI/2+Math.atan2(Math.max(0,x),-z);
        double eyeAngle=Math.atan2((eye.z()-corner.z())*sz,(eye.x()-corner.x())*sx),delta=theta-eyeAngle;
        if(Math.abs(delta)<=Math.PI*7/12)return p;
        // Intrinsic cone period is 270 degrees. Referencing the player's radial direction
        // makes the fully repaired far seam independent of which incident face is the root.
        if(delta>Math.PI*.75)delta-=Math.PI*1.5;else if(delta< -Math.PI*.75)delta+=Math.PI*1.5;
        double target=eyeAngle+delta+Math.signum(delta)*Math.PI/4*smooth(Math.PI*7/12,Math.PI*.75,Math.abs(delta));
        double shift=target-theta;if(shift>Math.PI)shift-=2*Math.PI;else if(shift< -Math.PI)shift+=2*Math.PI;
        double angle=shift*amplitude(Math.hypot(x,z));if(angle==0)return p;
        double c=Math.cos(angle),s=Math.sin(angle);
        return new Point(corner.x()+sx*(x*c-z*s),p.y(),corner.z()+sz*(x*s+z*c));
    }
    /** A common fixed grid welds fine and fallback edges. GUARD includes its 16*sqrt(2) footprint. */
    public Point flat(Point p){
        if(air.weight==1)return air.flat(p);
        var ground=ground(p);
        return air.weight==0?ground:ground.scale(1-air.weight).add(air.flat(p).scale(air.weight));
    }
    private Point ground(Point p){
        if(strength==0)return p;
        double x=Math.floor(p.x()/GRID)*GRID,z=Math.floor(p.z()/GRID)*GRID,u=(p.x()-x)/GRID,v=(p.z()-z)/GRID;
        var a=raw(new Point(x,0,z));var b=raw(new Point(x+GRID,0,z));var c=raw(new Point(x,0,z+GRID));var d=raw(new Point(x+GRID,0,z+GRID));
        return new Point(a.x()*(1-u)*(1-v)+b.x()*u*(1-v)+c.x()*(1-u)*v+d.x()*u*v,p.y(),a.z()*(1-u)*(1-v)+b.z()*u*(1-v)+c.z()*(1-u)*v+d.z()*u*v);
    }
    public Point point(Face face,Point local){var tile=chart.tile(face);if(tile==null)throw new IllegalArgumentException("Outside local net");return flat(tile.point(local));}
    public record GapQuad(Point a,Point b,Point c,Point d){}
    /** The ACTUAL remaining hole, not a red plane hidden under replacement terrain. */
    public List<GapQuad> residual(){
        var out=new ArrayList<GapQuad>();
        for(double x:new double[]{0,GroundSpace.SIZE})for(double z:new double[]{0,GroundSpace.SIZE}){
            double xs=x==0?1:-1,zs=z==0?1:-1,range=Math.min(GroundSpace.SIZE,clip+Math.hypot(eye.x()-x,eye.z()-z));
            if(Math.hypot(eye.x()-x,eye.z()-z)>clip)continue;
            for(double r=0;r<range&&r<GroundSpace.SIZE;r+=GRID){var a=flat(new Point(x-xs*r,0,z));var b=flat(new Point(x-xs*(r+GRID),0,z));var c=flat(new Point(x,0,z-zs*(r+GRID)));var d=flat(new Point(x,0,z-zs*r));if(b.sub(c).length()>1e-7||a.sub(d).length()>1e-7)out.add(new GapQuad(a,b,c,d));}
        }
        return out;
    }
}

package dev.starfold;

import dev.starfold.BentStripGeometry.Point;
import org.joml.Quaterniond;

/** Unit AABB walking and flight. Root changes transport pose AND orientation, never deform blocks. */
public final class GroundMotion {
    public record State(GroundSpace.Pose pose,double vertical,boolean grounded,boolean flying,boolean jumpHeld,boolean cut,double qx,double qy,double qz,double qw){
        public State{double n=qx*qx+qy*qy+qz*qz+qw*qw;if(pose==null||!Double.isFinite(vertical)||Math.abs(vertical)>3||!Double.isFinite(n)||Math.abs(n-1)>.001)throw new IllegalArgumentException("Body");}
        public State(GroundSpace.Pose p,double v,boolean grounded,boolean flying,boolean jump,boolean cut,Quaterniond q){this(p,v,grounded,flying,jump,cut,q.x,q.y,q.z,q.w);}
        public Quaterniond orientation(){return new Quaterniond(qx,qy,qz,qw);}
    }
    public static State spawn(GroundWorld w,GroundSpace.Pose pose,double yaw){if(!clear(w,pose))throw new IllegalStateException("Spawn occupied; no blocks removed");return new State(pose,0,false,false,false,false,new Quaterniond().rotationY(yaw));}
    public static State step(GroundWorld w,State old,PlanetMotion.Input in,boolean toggle){
        boolean flying=toggle?!old.flying:old.flying,jump=in.rise()>0;double vy=toggle?0:old.vertical;var p=old.pose.point();var chart=new GroundChart(old.pose.face());var q=GroundView.upright(in.orientation());
        var up=new Point(0,1,0);var f=PlanetMotion.direction(q,0,0,1);var l=PlanetMotion.direction(q,1,0,0);var horizontal=new Point(f.x(),0,f.z());if(horizontal.length()<1e-5)horizontal=l.cross(up);horizontal=PlanetSpace.unit(horizontal);var d=horizontal.scale(in.forward()).add(up.cross(horizontal).scale(in.left()));if(d.length()>1)d=PlanetSpace.unit(d);
        if(flying){vy=0;d=(in.direct()?f.scale(in.forward()).add(l.scale(in.left())):d).add(up.scale(in.rise()));d=d.scale((in.fast()?1.2:.35)/Math.max(1,d.length()));}
        else{if(old.grounded&&jump&&!old.jumpHeld)vy=.42;else vy=Math.max(-3,vy-.08);d=d.scale(in.fast()?.30:.215).add(up.scale(vy));}
        d=new Point(d.x(),Math.clamp(p.y()+d.y(),GroundSpace.MIN+1,GroundSpace.CEILING)-p.y(),d.z());
        var end=ChartLabMotion.sweep(p,d,(x,y,z)->w.material(chart,x,y,z)!=0);
        // No fabricated invisible wall. Explicitly refuse a step into an unavailable net quadrant.
        if(!chart.bodyFits(end))return new State(old.pose,0,old.grounded,flying,jump,true,q);
        boolean grounded=false;if(!flying){var probe=ChartLabMotion.sweep(end,new Point(0,-.06,0),(x,y,z)->w.material(chart,x,y,z)!=0);grounded=end.y()-probe.y()<.045;if(grounded&&vy<0||vy>0&&end.y()-p.y()<vy*.25)vy=0;}
        var r=GroundSpace.canonical(old.pose.face(),end);q.premul(new Quaterniond().rotationY(-r.turns()*Math.PI/2)).normalize();
        return new State(r.pose(),vy,grounded,flying,jump,false,q);
    }
    public static boolean clear(GroundWorld w,GroundSpace.Pose pose){var chart=new GroundChart(pose.face());var p=pose.point();if(!chart.bodyFits(p))return false;for(int x=(int)Math.floor(p.x()-.3);x<=Math.floor(p.x()+.3);x++)for(int y=(int)Math.floor(p.y()-.9);y<=Math.floor(p.y()+.9);y++)for(int z=(int)Math.floor(p.z()-.3);z<=Math.floor(p.z()+.3);z++)if(w.material(chart,x,y,z)!=0)return false;return true;}
    public static boolean intersects(GroundSpace.Pose pose,CubeSurfaceTopology.Cell cell){var t=new GroundChart(pose.face()).tile(cell.face());if(t==null)return false;var d=t.point(new Point(cell.u()+.5,cell.h()+.5,cell.v()+.5)).sub(pose.point());return Math.abs(d.x())<.802&&Math.abs(d.y())<1.402&&Math.abs(d.z())<.802;}
    private GroundMotion(){}
}

