package dev.starfold;

import dev.starfold.BentStripGeometry.Point;
import dev.starfold.CubeSurfaceTopology.Cell;

/** Unit DDA is the current runtime authority. The projection overload is retained only for
 * the archived alpha.52 geometry tests; client/server no longer call it. */
public final class GroundRay {
    public record Hit(int material,Cell owner,int x,int y,int z,Point normal,double distance,PlanetSpace.Side side){
        public Hit(int m,Cell c,int x,int y,int z,Point n,double d){this(m,c,x,y,z,n,d,null);}
        public boolean block(){return material>0;}
        public Cell neighbor(GroundChart chart){if(side!=null){var d=side.delta;return GroundSpace.TOPOLOGY.canonical(owner.add(d.u(),d.h(),d.v())).cell();}return chart.owner(x+(int)normal.x(),y+(int)normal.y(),z+(int)normal.z());}
    }
    /** Historical alpha.52 comparison path, not wired into current gameplay. */
    public static Hit trace(GroundWorld w,GroundProjection map,Point origin,Point direction,double reach){
        if(!origin.finite()||!direction.finite()||direction.length()<1e-9||!Double.isFinite(reach)||reach<0||reach>GroundSpace.REACH)throw new IllegalArgumentException("Local closed ray");
        if(map.interactive())return trace(w,map.chart,origin,direction,reach);
        var dir=PlanetSpace.unit(direction);Hit best=new Hit(0,null,0,0,0,new Point(0,1,0),reach);
        for(var f:GroundContact.facets(w,map,origin,reach)){var t=f.triangle();double distance=PlanetSpace.ray(t,origin,dir,best.distance());if(Double.isFinite(distance)){var c=t.owner();best=new Hit(f.material(),c,c.u(),c.h(),c.v(),t.normal(),distance,t.side());}}
        return best;
    }
    public static Hit trace(GroundWorld w,GroundChart chart,Point origin,Point direction,double reach){
        if(!origin.finite()||!direction.finite()||direction.length()<1e-9||!Double.isFinite(reach)||reach<0||reach>2048)throw new IllegalArgumentException("Ray");
        var d=PlanetSpace.unit(direction);int x=initial(origin.x(),d.x()),y=initial(origin.y(),d.y()),z=initial(origin.z(),d.z());double tx=edge(origin.x(),d.x(),x),ty=edge(origin.y(),d.y(),y),tz=edge(origin.z(),d.z(),z),distance=0;var normal=new Point(0,1,0);
        for(int i=0;i<4096;i++){
            var owner=chart.owner(x,y,z);if(owner==null)return new Hit(-1,null,x,y,z,normal,distance);int m=w.get(owner);if(m!=0)return new Hit(m,owner,x,y,z,normal,distance);
            double next=Math.min(tx,Math.min(ty,tz));if(next>reach)return new Hit(0,null,x,y,z,normal,reach);if(!Double.isFinite(next)||next<distance-1e-9)throw new IllegalStateException("DDA");distance=Math.max(next,distance);
            normal=tx<=ty&&tx<=tz?new Point(-Math.signum(d.x()),0,0):ty<=tz?new Point(0,-Math.signum(d.y()),0):new Point(0,0,-Math.signum(d.z()));
            if(tx<=next+1e-10){x+=(int)Math.signum(d.x());tx+=1/Math.abs(d.x());}if(ty<=next+1e-10){y+=(int)Math.signum(d.y());ty+=1/Math.abs(d.y());}if(tz<=next+1e-10){z+=(int)Math.signum(d.z());tz+=1/Math.abs(d.z());}
        }
        throw new IllegalStateException("Ray budget");
    }
    private static int initial(double p,double d){int i=(int)Math.floor(p);return d<0&&p==i?i-1:i;}
    private static double edge(double p,double d,int i){return Math.abs(d)<1e-12?Double.POSITIVE_INFINITY:((d>0?i+1:i)-p)/d;}
    private GroundRay(){}
}

