    static GroundSave fresh(boolean exists,int view){if(exists)throw new IllegalStateException("Existing ground save failed to load; refusing overwrite");var s=new GroundSave(new GroundWorld(GroundSpace.DEFAULT_MASK));s.setDirty();return s;}
    public static GroundSave get(ServerLevel level,int view){if(!GroundServer.is(level))throw new IllegalArgumentException("Dimension");var storage=level.getDataStorage();return storage.computeIfAbsent(new Factory<>(()->fresh(((dev.starfold.mixin.PlanetSpaceDataAccess)storage).starfold$spaceDataFile(FILE).exists(),view),GroundSave::load,null),FILE);}
