#version 150
in vec3 Position;
in vec2 UV0;
in vec4 Color;
uniform mat4 ModelViewMat;
uniform mat4 ProjMat;
uniform vec3 FlatOrigin, FlatU, FlatV;
uniform vec3 Eye;
uniform vec2 GapCorner, GapSigns;
uniform vec3 GapLimits;
uniform vec3 AirNormal, AirU, AirV;
uniform vec4 AirLimits; // weight, radius, anchor correction x/z (computed by GroundAir)
uniform float DetailPass;
out vec2 blockUV;
out vec2 displayedXZ;
out float airFacing;
flat out int materialFace;
flat out int tileId;
vec2 rawGap(vec2 p) {
    if (GapLimits.x == 0.0) return p;
    vec2 q = (p - GapCorner) * GapSigns;
    float r = length(q);
    if (r >= 2.0 * GapLimits.y) return p;
    if (!((q.x < 0.0 && q.y >= 0.0) || (q.y < 0.0 && q.x >= 0.0))) return p;
    vec2 e = (Eye.xz - GapCorner) * GapSigns;
    float theta = q.x < 0.0 ? 3.141592653589793 - atan(max(q.y,0.0),-q.x) : -1.5707963267948966 + atan(max(q.x,0.0),-q.y);
    float eyeAngle = atan(e.y,e.x), delta = theta-eyeAngle;
    if (abs(delta) <= 1.832595714594046) return p;
    if (delta > 2.356194490192345) delta -= 4.71238898038469;
    else if (delta < -2.356194490192345) delta += 4.71238898038469;
    float target = eyeAngle + delta + sign(delta) * 0.7853981633974483 * smoothstep(1.832595714594046, 2.356194490192345, abs(delta));
    float shift = target-theta;
    if (shift > 3.141592653589793) shift -= 6.283185307179586;
    else if (shift < -3.141592653589793) shift += 6.283185307179586;
    float minimumDistance = sqrt(dot(e,e) + r*r);
    float amplitude = GapLimits.x * smoothstep(56.0, 88.0, minimumDistance) * (1.0 - smoothstep(GapLimits.y, 2.0 * GapLimits.y, r));
    float angle = shift * amplitude;
    if (angle == 0.0) return p;
    float c = cos(angle), s = sin(angle);
    return GapCorner + GapSigns * vec2(q.x*c - q.y*s, q.x*s + q.y*c);
}
vec3 airDirection(vec2 p) {
    vec3 q = vec3(p.x-1024.0,1024.0,p.y-1024.0);
    if (p.x < 0.0) q = vec3(-1024.0,1024.0+p.x,p.y-1024.0);
    else if (p.x > 2048.0) q = vec3(1024.0,3072.0-p.x,p.y-1024.0);
    else if (p.y < 0.0) q = vec3(p.x-1024.0,1024.0+p.y,-1024.0);
    else if (p.y > 2048.0) q = vec3(p.x-1024.0,3072.0-p.y,1024.0);
    return normalize(q);
}
vec2 airRaw(vec2 p) {
    vec3 s = airDirection(p);
    vec3 d = (s-AirNormal) * (2.0*AirLimits.y / max(0.000001,1.0+dot(s,AirNormal)));
    return Eye.xz + vec2(dot(d,AirU),dot(d,AirV)) + AirLimits.zw;
}
vec2 node(vec2 p) {
    if (AirLimits.x == 0.0) return rawGap(p);
    if (AirLimits.x == 1.0) return airRaw(p);
    return mix(rawGap(p),airRaw(p),AirLimits.x);
}
vec2 repair(vec2 p) {
    if (GapLimits.x == 0.0 && AirLimits.x == 0.0) return p;
    vec2 low = floor(p / 16.0) * 16.0, f = (p-low)/16.0;
    return mix(mix(node(low), node(low+vec2(16.0,0.0)), f.x), mix(node(low+vec2(0.0,16.0)), node(low+vec2(16.0,16.0)), f.x), f.y);
}
void main() {
    vec3 p = Position;
    airFacing = 1.0;
    if (DetailPass >= 0.0) {
        p = FlatOrigin + Position.x * FlatU + Position.z * FlatV + vec3(0.0, Position.y, 0.0);
        // Exclude the remote projection pole, never a visible cut or a near block.
        if (AirLimits.x > 0.0) airFacing = dot(airDirection(p.xz),AirNormal);
        p.xz = repair(p.xz);
    }
    gl_Position = ProjMat * ModelViewMat * vec4(p, 1.0);
    displayedXZ = p.xz;
    blockUV = UV0;
    ivec4 ids = ivec4(round(Color * 255.0));
    materialFace = ids.r * 6 + ids.g;
    tileId = ids.b + ids.a * 256;
}

#version 150
uniform sampler2D Sampler0;
uniform sampler2D Sampler1;
uniform sampler2D Sampler2;
uniform vec4 ColorModulator;
uniform float FaceId, DetailPass;
uniform vec3 Eye, GapLimits;
uniform vec2 TextureFilter; // available last mip, mode: filtered/flat/original
in vec2 displayedXZ;
in float airFacing;
in vec2 blockUV;
flat in int materialFace;
flat in int tileId;
out vec4 fragColor;
vec3 linearColor(vec3 c) { return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(vec3(0.04045), c)); }
vec3 encodedColor(vec3 c) { return mix(c * 12.92, 1.055 * pow(max(c, vec3(0.0)), vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), c)); }
void main() {
    vec2 dx = dFdx(blockUV), dy = dFdy(blockUV);
    if (airFacing < 0.0 || length(displayedXZ - Eye.xz) > GapLimits.z) discard;
    if (DetailPass < 0.0) { fragColor = vec4(1.0, 0.12, 0.24, 1.0); return; }
    // Coverage replacement only: the resident fine tile draws EVERY corresponding face.
    // This is not a viewing-angle guard; a nonresident tile always keeps its complete fallback.
    if (DetailPass < 0.5 && texelFetch(Sampler2, ivec2(tileId % 128, tileId / 128 + int(FaceId) * 128), 0).r > 0.5) discard;
    vec4 bounds = texelFetch(Sampler1, ivec2(materialFace, 0), 0);
    vec3 average = texelFetch(Sampler1, ivec2(materialFace, 1), 0).rgb;
    vec2 span = bounds.zw - bounds.xy, atlasSize = vec2(textureSize(Sampler0, 0));
    vec2 spriteSize = max(vec2(1.0), span * atlasSize);
    vec2 tx = dx * spriteSize, ty = dy * spriteSize;
    float a = dot(tx,tx), b = dot(tx,ty), c = dot(ty,ty);
    float footprint = sqrt(max(0.0, 0.5 * (a+c+sqrt((a-c)*(a-c)+4.0*b*b))));
    float last = min(TextureFilter.x, floor(log2(min(spriteSize.x,spriteSize.y))));
    float capacity = exp2(max(0.0,last));
    float detail = 1.0 - smoothstep(0.5*capacity, capacity, footprint);
    if (TextureFilter.y > 1.5) detail = 1.0 - smoothstep(0.5, 2.0, max(length(dx),length(dy)));
    else if (TextureFilter.y > 0.5) detail = 0.0;
    vec3 albedo = average;
    if (detail > 0.0) {
        // Clamp to THIS sprite's highest sampled mip texel centres, not its atlas neighbours.
        float lod = clamp(ceil(log2(max(1.0,footprint))),0.0,max(0.0,last));
        vec2 margin = min(span*0.5,vec2(0.5*exp2(lod))/atlasSize);
        vec2 uv = bounds.xy + fract(blockUV) * span;
        if (TextureFilter.y < 1.5) uv = clamp(uv,bounds.xy+margin,bounds.zw-margin);
        vec3 sampled = textureGrad(Sampler0, uv, dx * span, dy * span).rgb;
        if (materialFace == 133) sampled *= vec3(127.0, 179.0, 79.0) / 255.0;
        albedo = mix(average, linearColor(sampled), detail);
    }
    int side = materialFace % 6;
    float light = side == 1 ? 1.0 : side == 0 ? 0.5 : 0.8;
    fragColor = vec4(encodedColor(albedo * light), 1.0) * ColorModulator;
}

#version 150
uniform sampler2D Sampler0, Sampler1;
uniform vec4 ColorModulator, OrbitLimits;
uniform vec3 Eye;
uniform vec2 TextureFilter; // available last mip, mode: filtered/flat/original
in vec2 displayedXZ;
in float sourceFacing;
in vec3 surfaceNormal;
in vec2 blockUV;
flat in int materialFace;
out vec4 fragColor;
vec3 linearColor(vec3 c) { return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(vec3(0.04045), c)); }
vec3 encodedColor(vec3 c) { return mix(c * 12.92, 1.055 * pow(max(c, vec3(0.0)), vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), c)); }
void main() {
    vec2 dx = dFdx(blockUV), dy = dFdy(blockUV);
    if(sourceFacing < OrbitLimits.w || length(displayedXZ-Eye.xz)>OrbitLimits.z) discard;
    vec4 bounds = texelFetch(Sampler1, ivec2(materialFace, 0), 0);
    vec3 average = texelFetch(Sampler1, ivec2(materialFace, 1), 0).rgb;
    vec2 span = bounds.zw - bounds.xy, atlasSize = vec2(textureSize(Sampler0, 0));
    vec2 spriteSize = max(vec2(1.0), span * atlasSize);
    vec2 tx = dx * spriteSize, ty = dy * spriteSize;
    float a = dot(tx,tx), b = dot(tx,ty), c = dot(ty,ty);
    float footprint = sqrt(max(0.0, 0.5 * (a+c+sqrt((a-c)*(a-c)+4.0*b*b))));
    float last = min(TextureFilter.x, floor(log2(min(spriteSize.x,spriteSize.y))));
    float capacity = exp2(max(0.0,last));
    float detail = 1.0 - smoothstep(0.5*capacity, capacity, footprint);
    if (TextureFilter.y > 1.5) detail = 1.0 - smoothstep(0.5, 2.0, max(length(dx),length(dy)));
    else if (TextureFilter.y > 0.5) detail = 0.0;
    vec3 albedo = average;
    if (detail > 0.0) {
        // Clamp to THIS sprite's highest sampled mip texel centres, not its atlas neighbours.
        float lod = clamp(ceil(log2(max(1.0,footprint))),0.0,max(0.0,last));
        vec2 margin = min(span*0.5,vec2(0.5*exp2(lod))/atlasSize);
        vec2 uv = bounds.xy + fract(blockUV) * span;
        if (TextureFilter.y < 1.5) uv = clamp(uv,bounds.xy+margin,bounds.zw-margin);
        vec3 sampled = textureGrad(Sampler0, uv, dx * span, dy * span).rgb;
        if (materialFace == 133) sampled *= vec3(127.0, 179.0, 79.0) / 255.0;
        albedo = mix(average, linearColor(sampled), detail);
    }
    int side = materialFace % 6;
    float light = side == 1 ? 1.0 : side == 0 ? 0.5 : 0.8;
    // Reuse the earlier Cubic exterior light, blended only in this new high stage.
    float spaceLight = 0.7 + 0.3 * max(0.0, dot(normalize(surfaceNormal), normalize(vec3(-1.0, 2.0, -0.5))));
    light = mix(light, spaceLight, OrbitLimits.x);
